import { _decorator, Component, Camera, view } from 'cc';
const { ccclass, property, executionOrder } = _decorator;

/**
 * 화면 비율에 따라 3D 월드 카메라의 orthoHeight를 조정해서,
 * 세로 화면에서도 최소한의 좌우 시야(minHalfWidth)를 항상 확보한다.
 * 가로(넓은 화면)에서는 baseOrthoHeight가 그대로 유지되도록 값을 잡아야 한다.
 */
@ccclass('CameraAspectFit')
@executionOrder(-200)
export class CameraAspectFit extends Component {
    @property({ displayName: '기본 orthoHeight', tooltip: '가로 화면 기준 카메라 orthoHeight (기존 값 유지용)' })
    baseOrthoHeight: number = 10;

    @property({ displayName: '최소 좌우 시야(절반 폭)', tooltip: '세로 화면에서도 이만큼의 월드 절반 폭이 보이도록 보장' })
    minHalfWidth: number = 18;

    private _camera: Camera | null = null;

    onLoad() {
        this._camera = this.getComponent(Camera);
        this._updateOrthoHeight();
        view.on('canvas-resize', this._updateOrthoHeight, this);
    }

    onDestroy() {
        view.off('canvas-resize', this._updateOrthoHeight, this);
    }

    private _updateOrthoHeight = () => {
        if (!this._camera) return;

        const px = view.getVisibleSizeInPixel();
        if (px.width <= 0 || px.height <= 0) return;

        const aspect = px.width / px.height;
        this._camera.orthoHeight = Math.max(this.baseOrthoHeight, this.minHalfWidth / aspect);
    };
}
